PURPLE='#7D3C98'; SKIN='#F5CBA7'; LBLUE='#AED6F1'; GOLD='#D4AC0D'; LGREY='#D5D8DC'
def box(x,y,w,h,c,t='',sz=16,tc=WHITE,r=8): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{c}"/>'+(text(x+w/2,y+h/2+sz*0.36,t,sz,tc) if t else '')
def pencil(x,y,a=-30,c=YEL,s=1): return f'<g transform="translate({x} {y}) rotate({a}) scale({s})"><rect x="-8" y="-50" width="16" height="80" fill="{c}"/><polygon points="-8,30 8,30 0,48" fill="{SAND}"/><polygon points="-3,41 3,41 0,48" fill="{INK}"/><rect x="-8" y="-60" width="16" height="10" fill="{PINK}"/><rect x="-8" y="-52" width="16" height="4" fill="{GREY}"/></g>'
def brush(x,y,a=30,s=1): return f'<g transform="translate({x} {y}) rotate({a}) scale({s})"><rect x="-5" y="-50" width="10" height="70" rx="3" fill="{BROWN}"/><rect x="-6" y="18" width="12" height="10" fill="{GREY}"/><path d="M-6 28 q6 22 12 0 Z" fill="{RED}"/></g>'
def scissors(x,y,s=1): return f'<g transform="translate({x} {y}) scale({s})"><line x1="-20" y1="-26" x2="12" y2="14" stroke="{DGREY}" stroke-width="5"/><line x1="20" y1="-26" x2="-12" y2="14" stroke="{DGREY}" stroke-width="5"/><circle cx="-14" cy="22" r="9" fill="none" stroke="{RED}" stroke-width="4"/><circle cx="14" cy="22" r="9" fill="none" stroke="{RED}" stroke-width="4"/></g>'
def figure(x,y,s=1,c=BLUE,pose='stand'):
    if pose=='run': limbs=f'<line x1="0" y1="-10" x2="-22" y2="4" stroke="{SKIN}" stroke-width="7" stroke-linecap="round"/><line x1="0" y1="-10" x2="20" y2="-26" stroke="{SKIN}" stroke-width="7" stroke-linecap="round"/><line x1="0" y1="16" x2="-20" y2="44" stroke="{DGREY}" stroke-width="8" stroke-linecap="round"/><line x1="0" y1="16" x2="22" y2="30" stroke="{DGREY}" stroke-width="8" stroke-linecap="round"/><line x1="22" y1="30" x2="16" y2="48" stroke="{DGREY}" stroke-width="8" stroke-linecap="round"/>'
    elif pose=='jump': limbs=f'<line x1="0" y1="-10" x2="-24" y2="-34" stroke="{SKIN}" stroke-width="7" stroke-linecap="round"/><line x1="0" y1="-10" x2="24" y2="-34" stroke="{SKIN}" stroke-width="7" stroke-linecap="round"/><line x1="0" y1="16" x2="-18" y2="36" stroke="{DGREY}" stroke-width="8" stroke-linecap="round"/><line x1="0" y1="16" x2="18" y2="36" stroke="{DGREY}" stroke-width="8" stroke-linecap="round"/>'
    else: limbs=f'<line x1="0" y1="-10" x2="-18" y2="14" stroke="{SKIN}" stroke-width="7" stroke-linecap="round"/><line x1="0" y1="-10" x2="18" y2="14" stroke="{SKIN}" stroke-width="7" stroke-linecap="round"/><line x1="0" y1="16" x2="-10" y2="48" stroke="{DGREY}" stroke-width="8" stroke-linecap="round"/><line x1="0" y1="16" x2="10" y2="48" stroke="{DGREY}" stroke-width="8" stroke-linecap="round"/>'
    return f'<g transform="translate({x} {y}) scale({s})"><circle cx="0" cy="-30" r="13" fill="{SKIN}"/><rect x="-11" y="-16" width="22" height="34" rx="7" fill="{c}"/>{limbs}</g>'
def castle_real(x,y,s=1): return f'<g transform="translate({x} {y}) scale({s})"><rect x="-70" y="-40" width="140" height="60" fill="{GREY}"/><rect x="-80" y="-70" width="30" height="90" fill="{DGREY}"/><rect x="50" y="-70" width="30" height="90" fill="{DGREY}"/>{"".join(f"<rect x=\"{xx}\" y=\"-80\" width=\"8\" height=\"12\" fill=\"{DGREY}\"/>" for xx in range(-80,-50,12))}{"".join(f"<rect x=\"{xx}\" y=\"-80\" width=\"8\" height=\"12\" fill=\"{DGREY}\"/>" for xx in range(50,80,12))}{"".join(f"<rect x=\"{xx}\" y=\"-48\" width=\"8\" height=\"10\" fill=\"{GREY}\"/>" for xx in range(-66,66,16))}<path d="M-12 20 v-30 a12 12 0 0 1 24 0 v30 Z" fill="{DBROWN}"/><rect x="-66" y="-30" width="8" height="14" fill="{INK}"/><rect x="56" y="-30" width="8" height="14" fill="{INK}"/></g>'
def castle_klee(x,y,s=1):
    cells=[(-70,-20,30,40,RED),(-40,-50,30,70,ORANGE),(-10,-20,30,40,YEL),(20,-60,30,80,PURPLE),(50,-20,30,40,GREEN),(-70,-45,30,25,BLUE),(-10,-50,30,30,PINK),(50,-50,30,30,WATER)]

    return f'<g transform="translate({x} {y}) scale({s})">'+''.join(f'<rect x="{a}" y="{b}" width="{w}" height="{h}" fill="{c}"/>' for a,b,w,h,c in cells)+f'<polygon points="-40,-50 -25,-70 -10,-50" fill="{RED}"/><polygon points="20,-60 35,-82 50,-60" fill="{BLUE}"/><circle cx="-50" cy="-80" r="14" fill="{ORANGE}"/></g>'
